          "choose": "切换新接口并标注新版本",
          "priority": 0,
          "decisions": [{"source_id": "m29", "quote": "这次选切换新接口并标注新版本。"}],
          "contexts": [{"source_id": "m3", "quote": "已有120个客户端依赖旧格式，客户端一个月内不会全部迁完。"}],
          "supersedes": ["m5"]
        },
        {
          "when": "新版公共接口方案尚待核对客户端清单",
          "choose": "只留在文档里，暂停发布",
          "priority": 0,
          "decisions": [{"source_id": "m45", "quote": "新版公共接口方案先停在文档里，等我核对客户端清单。"}],
          "contexts": [{"source_id": "m5", "quote": "暂时不要执行发布。"}],
          "supersedes": []
